    </div>
  )
}

function MeasurementTable(props: {
  axes: readonly AxisId[]
  draft: CalibrationDraft
  update: (change: (draft: CalibrationDraft) => CalibrationDraft) => void
}): JSX.Element {
  const entry = (axis: AxisId) => props.draft.entries[axis]

