                <MeasurementField
                  labelMode="cell"
                  id={`${axis}-inner`}
                  label={`${axis} inner (between the two walls)`}
                  value={entry(axis).inner}
                  onInput={(text) => set(axis, 'inner', text)}
                  warnings={warnings(axis, 'inner')}
                />
              </td>
            </tr>
          )}
        </For>
      </tbody>
    </table>
  )
}
```

