  const onName = (text: string): void => {
    setName(text)
    const trimmed = text.trim()
    props.update((draft) =>
      setChecked(
        setPrinterName(draft, trimmed),
        CHECKS.printerNameReady,
        trimmed !== '' && !props.printers.exists(trimmed) && outcome() !== null,
      ),
