out.typing = await nameField.evaluate((el) => {
  el.focus()
  const log = []
  let text = ''
  for (const char of 'Rig One') {
    text += char
    el.value = text
    el.dispatchEvent(new Event('input', { bubbles: true }))
    const root = el.getRootNode()
    log.push({
      value: el.value,
      connected: el.isConnected,
      focused: root.activeElement === el,
    })
  }
  return log
})
out.nextEnabled = await page.getByTestId('next').isEnabled()
