const click = async (l) => { await l.evaluate((el) => el.click()); await page.waitForTimeout(70) }
const next = () => click(page.getByTestId('next'))
const fill = async (label, value) => { await page.getByLabel(label).fill(value); await page.waitForTimeout(60) }
const style = (testid) =>
  page.getByTestId(testid).evaluate((el) => {
    const s = getComputedStyle(el)
    return {
      text: el.textContent.trim(),
      class: el.getAttribute('class'),
      background: s.backgroundColor,
      color: s.color,
      border: `${s.borderTopWidth} ${s.borderTopStyle} ${s.borderTopColor}`,
    }
  })

await page.reload()
await page.waitForTimeout(500)
await click(page.getByTestId('start'))
if ((await page.getByLabel(/digital calipers/).count()) > 0) {
